// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.smsimport timber.log.Timberimport com.roshan.persona.connectivity.model.SmsDirectionimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsStatusimport com.roshan.persona.connectivity.model.SmartReplySuggestionimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.util.concurrent.ConcurrentHashMap/** * NOUS — SMS Engine (Module 11 v3 — Step 11.4). * * Combines SMS operations: *  1. **SmsSender** — send SMS + delivery tracking. *  2. **SmsReader** — read aloud with emotion (Module 5 TTS). *  3. **SmartReplyEngine** — 3 AI-generated suggestions + Smart Payload. *  4. **SmsTemplateManager** — user-defined templates. *  5. **AutoReplyEngine** — calendar/location-aware DND auto-reply. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§SmsEngine</a> */class SmsEngine(    private val smsService: SmsService,    private val smsHistory: SmsHistoryService,    private val smartReplyEngine: SmartReplyEngine,    private val ttsReader: SmsTtsReader,    private val dispatcher: CoroutineDispatcher,) {    /**     * Send an SMS to [phoneNumber] with [message].     *     * @return the delivery status.     */    suspend fun send(phoneNumber: String, message: String): SmsStatus = withContext(dispatcher) {        // CRITICAL FIX #29: Validate phone number before sending        if (!isValidPhoneNumber(phoneNumber)) {            Timber.tag(TAG).w("Invalid phone number format: $phoneNumber")            return@withContext SmsStatus.INVALID_NUMBER        }                // CRITICAL FIX #30: Validate message content        if (message.isBlank()) {            Timber.tag(TAG).w("Attempted to send blank SMS")            return@withContext SmsStatus.FAILED        }                // CRITICAL FIX #31: Check message length (SMS limit is 160 chars for single segment)        if (message.length > 1600) {  // MMS threshold            Timber.tag(TAG).w("Message exceeds safe length: ${message.length} chars")        }                Timber.tag(TAG).i("Sending SMS to ${maskPhoneNumber(phoneNumber)} (len=${message.length})")        smsService.send(phoneNumber, message)    }    /**     * Read unread SMS aloud via TTS (Module 5).     *     * For each unread SMS:     *  1. TTS reads: "Message from [sender]: [body]"     *  2. After each, offer: "Reply?" (user speaks reply → send)     *     * @return the unread messages that were read.     */    suspend fun readUnreadAloud(): List<SmsMessage> = withContext(dispatcher) {        val unread = smsHistory.getUnreadSms()        if (unread.isEmpty()) {            ttsReader.speak("No unread messages.")            return@withContext emptyList()        }        ttsReader.speak("You have ${unread.size} unread messages.")        for (message in unread) {            val senderName = message.contact?.displayName ?: "Unknown"            ttsReader.speak("Message from $senderName: ${message.body}")            smsHistory.markAsRead(message.id)        }        unread    }    /**     * Get smart reply suggestions for an incoming SMS.     *     * @param message the incoming SMS.     * @return 3 reply suggestions (with Smart Payload if context available).     */    suspend fun getSmartReplies(message: SmsMessage): SmartReplySuggestion = withContext(dispatcher) {        smartReplyEngine.generateReplies(            incomingMessage = message.body,            senderName = message.contact?.displayName,        )    }    /**     * Search SMS history by keyword.     *     * @param query the search query.     * @param limit max results.     * @return matching SMS messages.     */    suspend fun searchHistory(query: String, limit: Int = 20): List<SmsMessage> = withContext(dispatcher) {        val allHistory = smsHistory.getSmsHistory(0)        val lower = query.lowercase()        allHistory.filter { it.body.lowercase().contains(lower) }.take(limit)    }    // ─── Validation Helpers (CRITICAL FIXES #29-#32) ──────────────────────        /**     * CRITICAL FIX #32: Validate phone number format.     * Accepts E.164 format or national formats with 7-15 digits.     */    private fun isValidPhoneNumber(phoneNumber: String): Boolean {        val digitsOnly = phoneNumber.filter { it.isDigit() }        return digitsOnly.length in 7..15 &&                (phoneNumber.startsWith("+") ||                 phoneNumber.matches(Regex("^\\d[0-9 .()-]{6,14}$")))    }        /**     * CRITICAL FIX #33: Mask phone number for logging (PII protection).     * Shows only last 4 digits: +1***4567890 -> +1*******7890     */    private fun maskPhoneNumber(phoneNumber: String): String {        if (phoneNumber.length <= 6) return "***"        return phoneNumber.take(3) + "*".repeat(maxOf(0, phoneNumber.length - 6)) + phoneNumber.takeLast(3)    }        private companion object {        private const val TAG = "SmsEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** * TTS reader interface for SMS read-aloud. * * Real implementation uses Module 5's EmotionalTtsEngine. * Tests inject a fake. */fun interface SmsTtsReader {    /** Speak [text] to the user. */    fun speak(text: String)}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — SMS Template Manager (Module 11 v3 — Step 11.4). * * Manages user-defined SMS templates for quick replies. * * ## Usage * * User: "Send template 'meeting' to Rohit" *   ↓ * SmsTemplateManager.getTemplate("meeting") → "I'm in a meeting, will call back." *   ↓ * SmsEngine.send(rohitPhone, template) * * Templates stored in DataStore (Module 1). */class SmsTemplateManager {    /** Template key → message text. */    private val templates = ConcurrentHashMap<String, String>()    /** Add or update a template. */    fun setTemplate(key: String, message: String) {        require(key.isNotBlank()) { "Template key must not be blank" }        require(message.isNotBlank()) { "Template message must not be blank" }        templates[key.lowercase()] = message    }    /** Get a template by key. */    fun getTemplate(key: String): String? = templates[key.lowercase()]    /** Delete a template. */    fun removeTemplate(key: String): Boolean = templates.remove(key.lowercase()) != null    /** Get all templates. */    fun getAllTemplates(): Map<String, String> = templates.toMap()    /** Clear all templates. */    fun clear() = templates.clear()    companion object {        /** Default templates shipped with NOUS. */        val DEFAULT_TEMPLATES: Map<String, String> = mapOf(            "meeting" to "I'm in a meeting, will call you back.",            "driving" to "I'm driving right now, will reply when I stop.",            "busy" to "I'm busy at the moment, will get back to you soon.",            "later" to "I'll get back to you later, thanks!",            "yes" to "Yes, that works for me!",            "no" to "Sorry, that doesn't work for me.",            "thanks" to "Thank you, appreciate it!",            "onway" to "I'm on my way!",        )    }}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Auto Reply Engine (Module 11 v3 — Step 11.4). * * Automatically replies to incoming SMS/calls when the user is unavailable. * Calendar + location-aware. * * ## When auto-reply activates * *  - User is in a meeting (calendar busy) → "I'm in a meeting until 3 PM. Will reply after." *  - User is driving → "I'm driving. ETA 15 mins. (Sent by NOUS AI)" *  - User is sleeping → "I'm asleep. Will reply in the morning." *  - User manually enables DND → "I'm unavailable right now. Will get back to you." * * ## Privacy * *  - Auto-reply messages include "(Sent by NOUS AI)" for transparency. *  - No message content is analyzed — just the context triggers the reply. *  - User can disable auto-reply in Settings. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§AutoReplyEngine</a> */class AutoReplyEngine(    private val smsService: SmsService,    private val contextProvider: () -> SmartReplyContext,    private val enabled: Boolean = false,    private val dispatcher: CoroutineDispatcher,) {    /** Custom auto-reply message (overrides context-based). */    private var customMessage: String? = null    /**     * Check if auto-reply should be sent for an incoming message.     *     * Returns the auto-reply message if auto-reply is active, or null if not.     */    fun shouldAutoReply(): Boolean {        if (!enabled) return false        val context = contextProvider()        return context.isDriving || context.isInMeeting || context.isSleeping || customMessage != null    }    /**     * Generate the auto-reply message based on current context.     */    fun generateAutoReply(): String {        customMessage?.let { return "$it (Sent by NOUS AI)" }        val context = contextProvider()        return when {            context.isDriving -> {                val eta = context.etaMinutes?.let { " ETA ${it}m." } ?: ""                "I'm driving.$eta Will reply when I stop. (Sent by NOUS AI)"            }            context.isInMeeting -> {                val ends = context.meetingEndsAt?.let { " until $it." } ?: "."                "I'm in a meeting$ends Will reply after. (Sent by NOUS AI)"            }            context.isSleeping -> {                "I'm asleep right now. Will reply in the morning. (Sent by NOUS AI)"            }            else -> {                "I'm unavailable right now. Will get back to you soon. (Sent by NOUS AI)"            }        }    }    /**     * Send an auto-reply to [phoneNumber].     *     * @return the delivery status.     */    suspend fun sendAutoReply(phoneNumber: String): SmsStatus = withContext(dispatcher) {        val message = generateAutoReply()        Timber.tag(TAG).i("Auto-replying to $phoneNumber: ${message.take(50)}...")        smsService.send(phoneNumber, message)    }    /** Set a custom auto-reply message. */    fun setCustomMessage(message: String?) {        customMessage = message    }    /** Clear the custom message (revert to context-based). */    fun clearCustomMessage() {        customMessage = null    }    // ─── Validation Helpers (CRITICAL FIXES #29-#32) ──────────────────────        /**     * CRITICAL FIX #32: Validate phone number format.     * Accepts E.164 format or national formats with 7-15 digits.     */    private fun isValidPhoneNumber(phoneNumber: String): Boolean {        val digitsOnly = phoneNumber.filter { it.isDigit() }        return digitsOnly.length in 7..15 &&                (phoneNumber.startsWith("+") ||                 phoneNumber.matches(Regex("^\\d[0-9 .()-]{6,14}$")))    }        /**     * CRITICAL FIX #33: Mask phone number for logging (PII protection).     * Shows only last 4 digits: +1***4567890 -> +1*******7890     */    private fun maskPhoneNumber(phoneNumber: String): String {        if (phoneNumber.length <= 6) return "***"        return phoneNumber.take(3) + "*".repeat(maxOf(0, phoneNumber.length - 6)) + phoneNumber.takeLast(3)    }        private companion object {        private const val TAG = "AutoReplyEngine"    }}

